@dataclass
class Actor:
    actor_id: str
    pos: Point
    hp: int
    max_hp: int
    attack: int
    faction: str
    glyph: str
    alive: bool = True
    statuses: dict[str, int] = field(default_factory=dict)
    shield: int = 0

    def __post_init__(self):
        if self.max_hp < 1 or self.hp < 0 or self.attack < 0 or self.shield < 0:
            raise ValueError("invalid actor statistics")
        self.hp = min(self.hp, self.max_hp)
        self.alive = self.hp > 0

    def move_to(self, point: Point):
        if not self.alive:
            raise ValueError("dead actors cannot move")
        self.pos = point

    def heal(self, amount: int) -> int:
        if amount < 0:
            raise ValueError("negative healing")
        old = self.hp
        self.hp = min(self.max_hp, self.hp + amount)
        self.alive = self.hp > 0
        return self.hp - old

    def receive(self, amount: int, is_poison: bool = False) -> int:
        if amount < 0:
            raise ValueError("negative damage")
        if is_poison:
            dealt = min(self.hp, amount)
            self.hp -= dealt
        else:
            shield_damage = min(self.shield, amount)
            remaining = amount - shield_damage
            if remaining > 0:
                hp_damage = min(self.hp, remaining)
                self.hp -= hp_damage
        self.alive = self.hp > 0
        return dealt

